else:
 s.close(); raise SystemExit('Communication interdite reussie')

from pathlib import Path; import os; assert os.geteuid()!=0; s=Path('/proc/self/status').read_text(); assert 'CapEff:\t0000000000000000' in s; assert 'NoNewPrivs:\t1' in s
try:
 Path('/write-forbidden').write_text('temoin')
except OSError:
 print('non root, sans capacites, no-new-privileges, racine non inscriptible')
else:
 raise SystemExit('racine inscriptible')

